  computeTimeScale,
  type TimelineItem,
} from "./timeline-utils";

function makeEvent(overrides: Partial<EventSnapshot> = {}): EventSnapshot {
  return {
    id: "e1",
    title: "Event 1",
    description: "",
    event_type: "operational",
    scheduled_pt_ms: 0,
    duration_ms: 30_000,
