describe("timeline-utils", () => {
  describe("computeTimelineItems", () => {
    it("returns empty arrays when no events or issues", () => {
      const result = computeTimelineItems([], [], 0);
      expect(result.eventItems).toEqual([]);
      expect(result.issueItems).toEqual([]);
    });

    it("maps a scheduled event to a timeline item", () => {
      const events = [
        makeEvent({ id: "e1", scheduled_pt_ms: 5000, duration_ms: 10_000 }),
      ];
      const { eventItems } = computeTimelineItems(events, [], 0);
      expect(eventItems).toHaveLength(1);
      expect(eventItems[0].id).toBe("e1");
      expect(eventItems[0].startMs).toBe(5000);
      expect(eventItems[0].endMs).toBe(15_000);
      expect(eventItems[0].kind).toBe("event");
    });

    it("uses started_at_pt_ms when event is running", () => {
      const events = [
        makeEvent({
          id: "e1",
          scheduled_pt_ms: 5000,
          duration_ms: 10_000,
          lifecycle: "running",
          started_at_pt_ms: 6000,
        }),
      ];
      const { eventItems } = computeTimelineItems(events, [], 20_000);
      expect(eventItems[0].startMs).toBe(6000);
      expect(eventItems[0].endMs).toBe(16_000);
    });

    it("uses completed_at_pt_ms for completed events", () => {
      const events = [
        makeEvent({
          id: "e1",
          lifecycle: "completed",
          started_at_pt_ms: 1000,
          completed_at_pt_ms: 8000,
        }),
      ];
      const { eventItems } = computeTimelineItems(events, [], 10_000);
      expect(eventItems[0].startMs).toBe(1000);
      expect(eventItems[0].endMs).toBe(8000);
    });

    it("uses playTimeMs as endMs for running events with no duration", () => {
      const events = [
        makeEvent({
          id: "e1",
          lifecycle: "running",
          duration_ms: null,
          started_at_pt_ms: 1000,
        }),
      ];
      const { eventItems } = computeTimelineItems(events, [], 50_000);
      expect(eventItems[0].endMs).toBe(50_000);
    });

    it("uses default 30s width for scheduled events with no duration", () => {
      const events = [
        makeEvent({
          id: "e1",
          lifecycle: "scheduled",
          duration_ms: null,
          scheduled_pt_ms: 2000,
        }),
      ];
      const { eventItems } = computeTimelineItems(events, [], 0);
      expect(eventItems[0].endMs).toBe(32_000);
    });

    it("filters out issues with no activated_at_pt_ms", () => {
      const issues = [makeIssue({ id: "i1", activated_at_pt_ms: null })];
      const { issueItems } = computeTimelineItems([], issues, 0);
      expect(issueItems).toHaveLength(0);
    });

    it("maps an active issue to a timeline item", () => {
      const issues = [
        makeIssue({
          id: "i1",
          lifecycle: "active",
          activated_at_pt_ms: 3000,
          auto_resolve_ms: 20_000,
        }),
      ];
      const { issueItems } = computeTimelineItems([], issues, 10_000);
      expect(issueItems).toHaveLength(1);
      expect(issueItems[0].startMs).toBe(3000);
      expect(issueItems[0].endMs).toBe(23_000);
      expect(issueItems[0].kind).toBe("issue");
    });

    it("uses resolved_at_pt_ms for resolved issues", () => {
      const issues = [
        makeIssue({
          id: "i1",
          lifecycle: "resolved",
          activated_at_pt_ms: 1000,
          resolved_at_pt_ms: 5000,
        }),
      ];
      const { issueItems } = computeTimelineItems([], issues, 10_000);
      expect(issueItems[0].endMs).toBe(5000);
    });

    it("uses playTimeMs for active issues with no auto_resolve", () => {
      const issues = [
        makeIssue({
          id: "i1",
          lifecycle: "active",
          activated_at_pt_ms: 2000,
          auto_resolve_ms: 0,
        }),
      ];
      const { issueItems } = computeTimelineItems([], issues, 15_000);
      expect(issueItems[0].endMs).toBe(15_000);
    });
  });

  describe("assignLanes", () => {
    it("assigns all non-overlapping items to lane 0", () => {
      const items: TimelineItem[] = [
        {
          id: "a",
          label: "A",
          startMs: 0,
          endMs: 100,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
        {
          id: "b",
          label: "B",
          startMs: 100,
          endMs: 200,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
        {
          id: "c",
          label: "C",
          startMs: 200,
          endMs: 300,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
      ];
      const result = assignLanes(items);
      expect(result.every((i) => i.lane === 0)).toBe(true);
    });

    it("stacks overlapping items into separate lanes", () => {
      const items: TimelineItem[] = [
        {
          id: "a",
          label: "A",
          startMs: 0,
          endMs: 200,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
        {
          id: "b",
          label: "B",
          startMs: 50,
          endMs: 150,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
        {
          id: "c",
          label: "C",
          startMs: 100,
          endMs: 250,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
      ];
      const result = assignLanes(items);
      const lanes = result.map((i) => i.lane);
      expect(lanes).toContain(0);
      expect(lanes).toContain(1);
      expect(Math.max(...lanes)).toBeGreaterThanOrEqual(1);
    });

    it("reuses lanes when items no longer overlap", () => {
      const items: TimelineItem[] = [
        {
          id: "a",
          label: "A",
          startMs: 0,
          endMs: 100,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
        {
          id: "b",
          label: "B",
          startMs: 50,
          endMs: 150,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
        {
          id: "c",
          label: "C",
          startMs: 150,
          endMs: 200,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
      ];
      const result = assignLanes(items);
      // 'c' starts at 150, 'a' ends at 100, so 'c' can reuse lane 0
      const cItem = result.find((i) => i.id === "c")!;
      expect(cItem.lane).toBe(0);
    });

    it("handles empty input", () => {
      expect(assignLanes([])).toEqual([]);
    });
  });

  describe("computeTimeScale", () => {
    it("returns reasonable scale for empty items", () => {
      const scale = computeTimeScale([], 60_000, 1200);
      expect(scale.totalMs).toBe(60_000);
      expect(scale.pxPerMs).toBeCloseTo(1200 / 60_000);
    });

    it("uses 110% of max end time with items", () => {
      const items: TimelineItem[] = [
        {
          id: "a",
          label: "A",
          startMs: 0,
          endMs: 100_000,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
      ];
      const scale = computeTimeScale(items, 50_000, 1200);
      expect(scale.totalMs).toBeCloseTo(110_000);
    });

    it("uses playTimeMs if it exceeds all item ends", () => {
      const items: TimelineItem[] = [
        {
          id: "a",
          label: "A",
          startMs: 0,
          endMs: 10_000,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
      ];
      const scale = computeTimeScale(items, 200_000, 1200);
      expect(scale.totalMs).toBeCloseTo(220_000);
    });

    it("returns valid pxPerMs ratio", () => {
      const items: TimelineItem[] = [
        {
          id: "a",
          label: "A",
          startMs: 0,
          endMs: 60_000,
          lifecycle: "",
          kind: "event",
          lane: 0,
        },
      ];
      const scale = computeTimeScale(items, 60_000, 1200);
      expect(scale.pxPerMs).toBeGreaterThan(0);
      expect(scale.pxPerMs * scale.totalMs).toBeCloseTo(1200);
    });
  });
});

import { describe, it, expect } from "vitest";
import type { ActiveDecision } from "../../core/decision-api.service";
import type { RoleDef } from "../../core/scenario-api.service";
import type { EventSnapshot } from "../../core/generated/state-changes.types";
import { buildRoleCards, extractRecRoleId } from "./role-card.types";

// ── Factories ────────────────────────────────────────────

function makeRole(overrides: Partial<RoleDef> = {}): RoleDef {
  return { id: "ops", label: "OPS", player_type: "advisor", ...overrides };
}

function makeEvent(overrides: Partial<EventSnapshot> = {}): EventSnapshot {
  return {
    id: "e1",
    title: "Event 1",
    description: "",
    event_type: "operational",
    scheduled_pt_ms: 0,
    duration_ms: 30_000,
    dependencies: [],
    triggered_issues: [],
    lifecycle: "running",
    started_at_pt_ms: 0,
    completed_at_pt_ms: null,
    target_roles: [],
    role_descriptions: {},
    ...overrides,
  };
}

function makeDecision(overrides: Partial<ActiveDecision> = {}): ActiveDecision {
  return {
    id: "d1",
    event_id: "e1",
    issue_id: null,
    title: "Decision 1",
    description: "Choose wisely",
    question_type: "single_choice",
    options: [
      { id: "o1", label: "Option A", score: 10, role: null },
      { id: "o2", label: "Option B", score: 5, role: null },
    ],
    completion_mode: "first_response",
    target_roles: ["ops"],
    timeout_ms: 60_000,
    max_selections: 1,
    status: "open",
    opened_at_pt_ms: 1000,
    closed_at_pt_ms: null,
    recommendations: {},
    selected_option_ids: [],
    ...overrides,
  };
}

// ── extractRecRoleId ─────────────────────────────────────

describe("extractRecRoleId", () => {
  it("extracts roleId from participantId:roleId format", () => {
    expect(extractRecRoleId("p1:ops")).toBe("ops");
  });

  it("returns bare key when no colon", () => {
    expect(extractRecRoleId("ops")).toBe("ops");
  });

  it("handles multiple colons (takes after first)", () => {
    expect(extractRecRoleId("p1:ops:extra")).toBe("ops:extra");
  });
});

// ── buildRoleCards ───────────────────────────────────────

describe("buildRoleCards", () => {
  it("returns empty array when no event and no decision", () => {
    const roles = [makeRole()];
    expect(buildRoleCards(roles, null, null, new Set(), true)).toEqual([]);
  });

  it("builds intel-only card from event role_descriptions", () => {
    const roles = [makeRole({ id: "ops", label: "OPS" })];
    const event = makeEvent({ role_descriptions: { ops: "Coordinate logistics" } });
    const cards = buildRoleCards(roles, event, null, new Set(), true);

    expect(cards).toHaveLength(1);
    expect(cards[0].roleId).toBe("ops");
    expect(cards[0].intel).toBe("Coordinate logistics");
    expect(cards[0].status).toBe("intel");
    expect(cards[0].decision).toBeNull();
  });

  it("builds active card when role is in decision target_roles", () => {
    const roles = [makeRole({ id: "ops" })];
    const decision = makeDecision({ target_roles: ["ops"] });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);

    expect(cards).toHaveLength(1);
    expect(cards[0].status).toBe("active");
    expect(cards[0].decision).toBe(decision);
  });

  it("marks card as done when role is in submittedRoles", () => {
    const roles = [makeRole({ id: "ops" })];
    const decision = makeDecision({ target_roles: ["ops"] });
    const submitted = new Set(["ops"]);
    const cards = buildRoleCards(roles, null, decision, submitted, true);

    expect(cards).toHaveLength(1);
    expect(cards[0].status).toBe("done");
  });

  it("filters out decision_maker when showDecisionMaker is false", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({ target_roles: ["co", "ops"] });
    const cards = buildRoleCards(roles, null, decision, new Set(), false);

    expect(cards).toHaveLength(1);
    expect(cards[0].roleId).toBe("ops");
  });

  it("includes decision_maker when showDecisionMaker is true", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({ target_roles: ["co", "ops"] });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);

    expect(cards).toHaveLength(2);
    expect(cards.map((c) => c.roleId)).toEqual(["co", "ops"]);
  });

  it("excludes roles with no intel and no decision", () => {
    const roles = [
      makeRole({ id: "ops" }),
      makeRole({ id: "intel", label: "INTEL" }),
    ];
    const event = makeEvent({ role_descriptions: { ops: "Brief" } });
    const cards = buildRoleCards(roles, event, null, new Set(), true);

    expect(cards).toHaveLength(1);
    expect(cards[0].roleId).toBe("ops");
  });

  // ── Advisor recs on decision_maker card ──

  it("populates advisorRecs on decision_maker card", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({
      target_roles: ["co", "ops"],
      recommendations: { "p1:ops": "o1" },
    });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);
    const coCard = cards.find((c) => c.roleId === "co")!;

    expect(coCard.advisorRecs).toHaveLength(1);
    expect(coCard.advisorRecs[0].roleId).toBe("ops");
    expect(coCard.advisorRecs[0].selection).toBe("Option A");
  });

  it("shows pending advisor rec when no recommendation yet", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({
      target_roles: ["co", "ops"],
      recommendations: {},
    });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);
    const coCard = cards.find((c) => c.roleId === "co")!;

    expect(coCard.advisorRecs[0].selection).toBeNull();
  });

  it("handles bare roleId keys in recommendations (legacy format)", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({
      target_roles: ["co", "ops"],
      recommendations: { ops: "o2" },
    });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);
    const coCard = cards.find((c) => c.roleId === "co")!;

    expect(coCard.advisorRecs[0].selection).toBe("Option B");
  });

  it("does not populate advisorRecs on advisor cards", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({ target_roles: ["co", "ops"] });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);
    const opsCard = cards.find((c) => c.roleId === "ops")!;

    expect(opsCard.advisorRecs).toEqual([]);
  });

  it("resolves advisor labels from allRoles when roles is filtered to CO only", () => {
    const coOnly = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
    ];
    const allRoles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "nav", label: "Navigator", player_type: "advisor" }),
      makeRole({ id: "pwo", label: "Principal Warfare Officer", player_type: "advisor" }),
    ];
    const decision = makeDecision({
      target_roles: ["co", "nav", "pwo"],
      recommendations: { "p1:nav": "o1" },
    });
    const cards = buildRoleCards(coOnly, null, decision, new Set(), true, allRoles);
    const coCard = cards.find((c) => c.roleId === "co")!;

    expect(coCard.advisorRecs).toHaveLength(2);
    expect(coCard.advisorRecs[0].roleLabel).toBe("Navigator");
    expect(coCard.advisorRecs[0].selection).toBe("Option A");
    expect(coCard.advisorRecs[1].roleLabel).toBe("Principal Warfare Officer");
    expect(coCard.advisorRecs[1].selection).toBeNull();
  });

  it("falls back option ID as label when option not found", () => {
    const roles = [
      makeRole({ id: "co", label: "CO", player_type: "decision_maker" }),
      makeRole({ id: "ops", label: "OPS", player_type: "advisor" }),
    ];
    const decision = makeDecision({
      target_roles: ["co", "ops"],
      recommendations: { "p1:ops": "unknown-opt" },
    });
    const cards = buildRoleCards(roles, null, decision, new Set(), true);
    const coCard = cards.find((c) => c.roleId === "co")!;

    expect(coCard.advisorRecs[0].selection).toBe("unknown-opt");
  });
});

